{"command": "/tmp/opensip-architecture-review-env/bin/python -I -B << 'PY'
import json,re
from pathlib import Path
KIT = Path("/tmp/opensip-design-corrections/consumer-b.v11/subject")

# headings from native-evidence
ne = (KIT/"docs/v2/contracts/product-v1/native-evidence.md").read_text()
print("=== native-evidence headings ===")
for i,line in enumerate(ne.splitlines(),1):
    if line.startswith("#"):
        print(f"{i:5d} {line[:120]}")

print("\n=== identity-and-evidence headings ===")
ie = (KIT/"docs/v2/contracts/product-v1/identity-and-evidence.md").read_text()
for i,line in enumerate(ie.splitlines(),1):
    if line.startswith("#"):
        print(f"{i:5d} {line[:120]}")

print("\n=== workflows headings ===")
wf = (KIT/"docs/v2/contracts/product-v1/workflows-and-surfaces.md").read_text()
for i,line in enumerate(wf.splitlines(),1):
    if line.startswith("#"):
        print(f"{i:5d} {line[:120]}")

print("\n=== security headings ===")
sec = (KIT/"docs/v2/contracts/product-v1/security-and-lifecycle.md").read_text()
for i,line in enumerate(sec.splitlines(),1):
    if line.startswith("#"):
        print(f"{i:5d} {line[:120]}")
PY
