        return b"null"
    if t is bool:
        return b"true" if value else b"false"
    if t is int:
        return encode_c_int(value)
    if t is float:
        raise AdmissionError("FLOAT_FORBIDDEN", "floating-point values are forbidden")
    if t is str:
        return encode_c_string(value)
