    if "\x00" in domain:
        raise AdmissionError("DOMAIN_NUL", "domain must not contain NUL")
    cx = C(descriptor)
    return (
        PRODUCT_PREFIX
        + b"\x00"
        + domain.encode("ascii")
        + b"\x00"
        + len(cx).to_bytes(8, "big")
        + cx
