def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def parse_h_frame(frame: bytes) -> tuple[str, bytes]:
    """Parse an H preimage frame. Returns (domain, C(X) bytes)."""
