    encoded = encode(value)
    decoded = decode(encoded)
    reencoded = encode(decoded)
    return {
        "encodedHex": encoded.hex(),
        "decoded": decoded,
        "reencodedHex": reencoded.hex(),
        "roundTripBytesEqual": encoded == reencoded,
        "valueEqual": decoded == value,
    }
