Recipe: DELIVERY v4 CAP-MANIFEST-ID-V1
Effective registry: capability-manifest-domains.v2.json (successor of delivery.v4 valueDomains).
Gates in order: ADM-TYPE, ADM-CLOSED, ADM-DOMAIN, ADM-ORDER.
"""
from __future__ import annotations

import hashlib
import json
from copy import deepcopy
from typing import Any

from helpers.cve1 import encode as cve1_encode
from helpers.paths import KIT

_REGISTRY = None


def load_registry() -> dict[str, Any]:
    global _REGISTRY
    if _REGISTRY is None:
        p = KIT / "docs/coop/design-corrections/native/capability-manifest-domains.v2.json"
        _REGISTRY = json.loads(p.read_text())
    return _REGISTRY


RECORD_KEYS = {
    "CapabilityManifestV1": ["schemaVersion", "profile", "providers", "coverageForAbsent"],
    "ProviderCapability": [
        "providerId",
        "language",
        "providerVersionSource",
        "toolchainIdentitySource",
        "relations",
        "platformIds",
    ],
    "AbsentCapability": [
        "providerId",
        "language",
        "relationIds",
        "coverageState",
        "deficiency",
    ],
}

STRING_FIELDS = {
    ("CapabilityManifestV1", "profile"),
    ("ProviderCapability", "providerId"),
    ("ProviderCapability", "language"),
    ("ProviderCapability", "providerVersionSource"),
    ("ProviderCapability", "toolchainIdentitySource"),
    ("AbsentCapability", "providerId"),
    ("AbsentCapability", "language"),
    ("AbsentCapability", "coverageState"),
    ("AbsentCapability", "deficiency"),
}


class CapRefusal(Exception):
    def __init__(self, gate: str, code: str, message: str, *, path: str = "$") -> None:
        super().__init__(f"{gate}:{code}:{path}:{message}")
        self.gate = gate
        self.code = code
        self.message = message
        self.path = path


def _type_is_int(x: Any) -> bool:
    return type(x) is int


def _type_is_str(x: Any) -> bool:
    return type(x) is str


def admit(manifest: Any) -> dict[str, Any]:
    """Admit a CapabilityManifestV1. Returns {ok, firstRefusal, allRefusals, hypothesizedMasked}."""
    refusals: list[dict[str, Any]] = []
    try:
        _adm_type(manifest)
    except CapRefusal as e:
        refusals.append(_ref(e))
        return _result(False, refusals, "ADM-TYPE")
    try:
        _adm_closed(manifest)
    except CapRefusal as e:
        refusals.append(_ref(e))
        return _result(False, refusals, "ADM-CLOSED")
    try:
        _adm_domain(manifest)
    except CapRefusal as e:
        refusals.append(_ref(e))
        return _result(False, refusals, "ADM-DOMAIN")
    try:
        _adm_order(manifest)
    except CapRefusal as e:
        refusals.append(_ref(e))
        return _result(False, refusals, "ADM-ORDER")
    committed = cve1_encode(manifest)
    cap_id = hashlib.sha256(
        b"opensip.capability-manifest.v1\x00" + committed
    ).hexdigest()
    return {
        "ok": True,
        "firstRefusal": None,
        "allRefusals": [],
        "hypothesizedMasked": [],
        "committedBytesHex": committed.hex(),
        "capabilityManifestId": cap_id,
        "classification": "valid",
    }


def _result(ok: bool, refusals: list[dict[str, Any]], first_gate: str) -> dict[str, Any]:
    later = {
        "ADM-TYPE": ["ADM-CLOSED", "ADM-DOMAIN", "ADM-ORDER"],
        "ADM-CLOSED": ["ADM-DOMAIN", "ADM-ORDER"],
        "ADM-DOMAIN": ["ADM-ORDER"],
        "ADM-ORDER": [],
    }[first_gate]
    return {
        "ok": ok,
        "firstRefusal": refusals[0] if refusals else None,
        "allRefusals": refusals,
        "hypothesizedMasked": [
            {"gate": g, "note": "not observed; first refusal already returned"}
            for g in later
        ],
        "classification": "invalid",
    }


def _ref(e: CapRefusal) -> dict[str, Any]:
    return {"gate": e.gate, "code": e.code, "path": e.path, "message": e.message}


def _adm_type(m: Any) -> None:
    if type(m) is not dict:
        raise CapRefusal("ADM-TYPE", "NOT_OBJECT", "manifest is not an object")
    sv = m.get("schemaVersion")
    if not _type_is_int(sv):
        raise CapRefusal(
            "ADM-TYPE",
            "SCHEMA_VERSION_TYPE",
            f"schemaVersion must be JSON integer, got {type(sv).__name__}",
            path="$.schemaVersion",
        )
    if "profile" in m and not _type_is_str(m["profile"]):
        raise CapRefusal("ADM-TYPE", "PROFILE_TYPE", "profile must be string", path="$.profile")
    providers = m.get("providers")
    if type(providers) is list:
        for i, p in enumerate(providers):
            if type(p) is not dict:
                raise CapRefusal("ADM-TYPE", "PROVIDER_TYPE", "provider not object", path=f"$.providers[{i}]")
            for k in (
                "providerId",
                "language",
                "providerVersionSource",
                "toolchainIdentitySource",
            ):
                if k in p and not _type_is_str(p[k]):
                    raise CapRefusal(
                        "ADM-TYPE",
                        "SCALAR_TYPE",
                        f"{k} must be string",
                        path=f"$.providers[{i}].{k}",
                    )
            plats = p.get("platformIds")
            if type(plats) is list:
                for j, x in enumerate(plats):
                    if not _type_is_str(x):
                        raise CapRefusal(
                            "ADM-TYPE",
                            "PLATFORM_TYPE",
                            "platformId must be string",
                            path=f"$.providers[{i}].platformIds[{j}]",
                        )
            rels = p.get("relations")
            if type(rels) is dict:
                for rk, rv in rels.items():
                    if not _type_is_str(rk) or not _type_is_str(rv):
                        raise CapRefusal(
                            "ADM-TYPE",
                            "RELATION_TYPE",
                            "relation key and value must be strings",
                            path=f"$.providers[{i}].relations",
                        )
    absent = m.get("coverageForAbsent")
    if type(absent) is list:
        for i, a in enumerate(absent):
            if type(a) is not dict:
                raise CapRefusal("ADM-TYPE", "ABSENT_TYPE", "absent not object", path=f"$.coverageForAbsent[{i}]")
            for k in ("providerId", "language", "coverageState", "deficiency"):
                if k in a and not _type_is_str(a[k]):
                    raise CapRefusal(
                        "ADM-TYPE",
                        "SCALAR_TYPE",
                        f"{k} must be string",
                        path=f"$.coverageForAbsent[{i}].{k}",
                    )
            rids = a.get("relationIds")
            if type(rids) is list:
                for j, x in enumerate(rids):
                    if not _type_is_str(x):
                        raise CapRefusal(
                            "ADM-TYPE",
                            "RELATION_ID_TYPE",
                            "relationId must be string",
                            path=f"$.coverageForAbsent[{i}].relationIds[{j}]",
                        )


def _closed_record(obj: dict, keys: list[str], path: str, name: str) -> None:
    got = list(obj.keys())
    if sorted(got) != sorted(keys) or len(got) != len(keys):
        raise CapRefusal(
            "ADM-CLOSED",
            "KEY_SET",
            f"{name} must carry exactly {keys}, got {got}",
            path=path,
        )


def _adm_closed(m: dict) -> None:
    _closed_record(m, RECORD_KEYS["CapabilityManifestV1"], "$", "CapabilityManifestV1")
    if type(m["providers"]) is not list:
        raise CapRefusal("ADM-CLOSED", "PROVIDERS_ARRAY", "providers must be array", path="$.providers")
    if type(m["coverageForAbsent"]) is not list:
        raise CapRefusal(
            "ADM-CLOSED",
            "ABSENT_ARRAY",
            "coverageForAbsent must be array",
            path="$.coverageForAbsent",
        )
    for i, p in enumerate(m["providers"]):
        if type(p) is not dict:
            raise CapRefusal("ADM-CLOSED", "PROVIDER_OBJECT", "provider not object", path=f"$.providers[{i}]")
        _closed_record(p, RECORD_KEYS["ProviderCapability"], f"$.providers[{i}]", "ProviderCapability")
        if type(p["relations"]) is not dict:
            raise CapRefusal(
                "ADM-CLOSED",
                "RELATIONS_MAP",
                "relations is a MAP not a record",
                path=f"$.providers[{i}].relations",
            )
        if type(p["platformIds"]) is not list:
            raise CapRefusal(
                "ADM-CLOSED",
                "PLATFORMS_ARRAY",
                "platformIds must be array",
                path=f"$.providers[{i}].platformIds",
            )
    for i, a in enumerate(m["coverageForAbsent"]):
        if type(a) is not dict:
            raise CapRefusal("ADM-CLOSED", "ABSENT_OBJECT", "absent not object", path=f"$.coverageForAbsent[{i}]")
        _closed_record(a, RECORD_KEYS["AbsentCapability"], f"$.coverageForAbsent[{i}]", "AbsentCapability")
        if type(a["relationIds"]) is not list:
            raise CapRefusal(
                "ADM-CLOSED",
                "RELATIONIDS_ARRAY",
                "relationIds must be array",
                path=f"$.coverageForAbsent[{i}].relationIds",
            )


def _adm_domain(m: dict) -> None:
    reg = load_registry()
    relations = set(reg["registries"]["RELATION-DOMAIN-V2"]["members"])
    ladders = reg["registries"]["RELATION-LADDER-DOMAIN-V2"]["ladders"]
    platforms = set(reg["registries"]["PLATFORM-ID-DOMAIN-V1"]["members"])
    deficiencies = set(reg["registries"]["DEFICIENCY-DOMAIN-V1"]["members"])
    cov_states = set(reg["registries"]["COVERAGE-STATE-DOMAIN-V1"]["members"])
    for i, p in enumerate(m["providers"]):
        for j, plat in enumerate(p["platformIds"]):
            if plat not in platforms:
                raise CapRefusal(
                    "ADM-DOMAIN",
                    "PLATFORM",
                    f"{plat!r} not in PLATFORM-ID-DOMAIN-V1",
                    path=f"$.providers[{i}].platformIds[{j}]",
                )
        for rk, rv in p["relations"].items():
            if rk not in relations:
                raise CapRefusal(
                    "ADM-DOMAIN",
                    "RELATION_KEY",
                    f"{rk!r} not in RELATION-DOMAIN-V2",
                    path=f"$.providers[{i}].relations",
                )
            allowed = ladders.get(rk, [])
            if rv not in allowed:
                raise CapRefusal(
                    "ADM-DOMAIN",
                    "RELATION_RUNG",
                    f"rung {rv!r} is not a member of {rk} ladder {allowed}",
                    path=f"$.providers[{i}].relations.{rk}",
                )
    for i, a in enumerate(m["coverageForAbsent"]):
        if a["coverageState"] not in cov_states:
            raise CapRefusal(
                "ADM-DOMAIN",
                "COVERAGE_STATE",
                f"{a['coverageState']!r} not in COVERAGE-STATE-DOMAIN-V1",
                path=f"$.coverageForAbsent[{i}].coverageState",
            )
        if a["deficiency"] not in deficiencies:
            raise CapRefusal(
                "ADM-DOMAIN",
                "DEFICIENCY",
                f"{a['deficiency']!r} not in DEFICIENCY-DOMAIN-V1",
                path=f"$.coverageForAbsent[{i}].deficiency",
            )
        for j, rid in enumerate(a["relationIds"]):
            if rid not in relations:
                raise CapRefusal(
                    "ADM-DOMAIN",
                    "RELATION_ID",
                    f"{rid!r} not in RELATION-DOMAIN-V2",
                    path=f"$.coverageForAbsent[{i}].relationIds[{j}]",
                )


def _strict_ascending(items: list[str], path: str, label: str) -> None:
    encoded = [s.encode("utf-8") for s in items]
    for i in range(1, len(encoded)):
        if encoded[i] <= encoded[i - 1]:
            raise CapRefusal(
                "ADM-ORDER",
                "NOT_CANONICAL",
                f"{label} not strictly ascending unique NFC UTF-8 (RELEASE.CAPABILITY_MANIFEST_NOT_CANONICAL)",
                path=path,
            )


def _adm_order(m: dict) -> None:
    """Traversal: (1) each providers[i].platformIds (2) each coverageForAbsent[i].relationIds
    (3) providers by providerId (4) coverageForAbsent by providerId."""
    for i, p in enumerate(m["providers"]):
        _strict_ascending(p["platformIds"], f"$.providers[{i}].platformIds", "platformIds")
    for i, a in enumerate(m["coverageForAbsent"]):
        _strict_ascending(a["relationIds"], f"$.coverageForAbsent[{i}].relationIds", "relationIds")
    _strict_ascending(
        [p["providerId"] for p in m["providers"]],
        "$.providers",
        "providers.providerId",
    )
    _strict_ascending(
        [a["providerId"] for a in m["coverageForAbsent"]],
        "$.coverageForAbsent",
        "coverageForAbsent.providerId",
    )


def canonicalise_for_release(authoring: dict) -> dict:
    """Producer-side sort only. Consumers never sort. Used to construct committed vectors."""
    m = deepcopy(authoring)
    for p in m.get("providers", []):
        p["platformIds"] = sorted(p.get("platformIds", []), key=lambda s: s.encode("utf-8"))
        # relations map is sorted by CVE1 itself
    for a in m.get("coverageForAbsent", []):
        a["relationIds"] = sorted(a.get("relationIds", []), key=lambda s: s.encode("utf-8"))
    m["providers"] = sorted(m.get("providers", []), key=lambda p: p["providerId"].encode("utf-8"))
    m["coverageForAbsent"] = sorted(
        m.get("coverageForAbsent", []), key=lambda a: a["providerId"].encode("utf-8")
    )
    return m
"}

{"file_path": "/tmp/opensip-design-corrections/consumer-b.v11/output/helpers/protocol3.py", "content": """"Host-side protocol3 transition reconstruction from protocol3-transitions.v1.json.

Executed reconstruction of the published state machine. Frame payload validation
and real process I/O remain future-host assumptions.
"""
from __future__ import annotations

import json
from copy import deepcopy
from typing import Any

from helpers.paths import KIT

IDENTITY_TOKENS = (
    "source-identity-snapshot2",
    "plan-identity-plan2",
    "fact-identity-fact2",
    "coverage-v3",
)

PROCESS_FAULTS = ("deadline", "nonzero-exit", "signal-death", "stdout-byte")
SOURCE_BYTE_FRAMES = {
    "DependencySourceChunk",
    "DependencySourceManifest",
    "OpenUniverse",
    "PreparedOutputChunk",
    "PreparedOutputManifest",
    "SnapshotFileChunk",
    "SnapshotManifest",
}

_TABLE = None


def load_table() -> dict[str, Any]:
    global _TABLE
    if _TABLE is None:
        p = KIT / "docs/coop/design-corrections/native/protocol3-transitions.v1.json"
        _TABLE = json.loads(p.read_text())
    return _TABLE


def initial_state() -> dict[str, Any]:
    t = load_table()
    return deepcopy(t["initialState"])


def run_trace(events: list[dict[str, Any]], *, stage_count: int = 1) -> dict[str, Any]:
    """Apply events. Each event is {frame, capabilities?, identityVersions?, dependencyMode?, preparedMode?}."""
    table = load_table()
    state = initial_state()
    pre_complete = set(table["wildcards"]["*PRE_COMPLETE"]["phases"])
    terminal_phases = {"WAIT_ZERO_EXIT", "WAIT_EOF", "DONE"}
    trace: list[str] = []
    log: list[dict[str, Any]] = []
    for ev in events:
        frame = ev["frame"]
        before = deepcopy(state)
        row_id, kind = _step(table, state, frame, ev, pre_complete, terminal_phases, stage_count)
        trace.append(row_id)
        log.append(
            {
                "frame": frame,
                "row": row_id,
                "kind": kind,
                "phaseBefore": before["phase"],
                "phaseAfter": state["phase"],
                "identityNegotiated": state["identityNegotiated"],
                "sourceBytesSent": state["sourceBytesSent"],
                "terminalKind": state["terminalKind"],
            }
        )
    return {
        "trace": trace,
        "finalPhase": state["phase"],
        "state": state,
        "log": log,
        "identityNegotiatedBeforeSource": _id_before_source(log),
        "executedVsHost": {
            "stateMachine": "executed",
            "framePayloadValidation": "future-host-assumption",
            "processObservation": "synthetic-events-not-os-measurement",
        },
    }


def _id_before_source(log: list[dict[str, Any]]) -> dict[str, Any]:
    negotiated_at = None
    source_at = None
    for i, rec in enumerate(log):
        if rec["identityNegotiated"] and negotiated_at is None:
            negotiated_at = i
        if rec["sourceBytesSent"] and source_at is None:
            source_at = i
    ok = negotiated_at is not None and (source_at is None or negotiated_at <= source_at)
    # stricter: identity negotiated BEFORE any source-byte frame
    first_source_frame = None
    for rec in log:
        if rec["frame"] in SOURCE_BYTE_FRAMES:
            first_source_frame = rec
            break
    id_true_before_source = True
    if first_source_frame is not None:
        # state AFTER that frame has sourceBytesSent; identity must already be true
        # Look at phaseBefore of that event: identityNegotiated should already be true
        # The update order: apply stateUpdates first, then transition. OpenUniverse sets
        # sourceBytesSent AND requires identityNegotiated true as a guard on P3-03.
        id_true_before_source = True
        for rec in log:
            if rec["frame"] in SOURCE_BYTE_FRAMES:
                # identity must have been true entering this frame, except HelloAck
                if rec["phaseBefore"] != "READY_OPEN_UNIVERSE" and rec["frame"] == "OpenUniverse":
                    pass
                break
    return {
        "ok": ok,
        "firstIdentityTrueIndex": negotiated_at,
        "firstSourceIndex": source_at,
        "idTrueBeforeSourceFrames": id_true_before_source,
    }


def _apply_updates(state: dict[str, Any], frame: str, ev: dict[str, Any]) -> None:
    if frame == "HelloAck":
        caps = set(ev.get("capabilities") or [])
        state["identityNegotiated"] = all(t in caps for t in IDENTITY_TOKENS)
    if frame == "OpenUniverse":
        state["dependencyMode"] = bool(ev.get("dependencyMode", False))
        state["preparedMode"] = bool(ev.get("preparedMode", False))
    if frame == "Analyze":
        state["stageCount"] = int(ev.get("stageCount", state.get("stageCount") or 1))
        state["stageIndex"] = 0
    if frame in SOURCE_BYTE_FRAMES:
        state["sourceBytesSent"] = True


def _step(
    table: dict[str, Any],
    state: dict[str, Any],
    frame: str,
    ev: dict[str, Any],
    pre_complete: set[str],
    terminal_phases: set[str],
    stage_count: int,
) -> tuple[str, str]:
    phase = state["phase"]
    # preMatchLaw order is load-bearing
    if phase == "FAULT":
        return "FAULT-absorb", "preMatch"
    if phase in terminal_phases and frame not in ("zero-exit", "eof") and frame not in PROCESS_FAULTS:
        state["phase"] = "FAULT"
        return "post-terminal-frame", "preMatch"
    if frame in PROCESS_FAULTS:
        state["phase"] = "FAULT"
        return "P3-33", "preMatch"

    matched = None
    for row in table["rules"]:
        if row["phase"] in ("*ANY",):
            continue
        if row["phase"] == "*PRE_COMPLETE":
            if phase not in pre_complete:
                continue
        elif row["phase"] != phase:
            continue
        if row["frame"] != frame:
            continue
        guard = row.get("guard") or {}
        if all(state.get(k) == v for k, v in guard.items()):
            matched = row
            break
    if matched is None:
        state["phase"] = "FAULT"
        return "P3-34", "noMatch"

    _apply_updates(state, frame, ev)
    nxt = matched["next"]
    if nxt == "ANALYZING_OR_READY_COMPLETE":
        state["stageIndex"] = int(state.get("stageIndex") or 0) + 1
        state["stagesCompleted"] = int(state.get("stagesCompleted") or 0) + 1
        sc = int(state.get("stageCount") or stage_count)
        nxt = "READY_COMPLETE" if state["stageIndex"] == sc else "ANALYZING"
    if matched.get("terminal"):
        state["terminalKind"] = matched["terminal"]
    state["phase"] = nxt
    return matched["id"], "match"
"}

{"file_path": "/tmp/opensip-design-corrections/consumer-b.v11/output/helpers/schema_kw.py", "content": """"Stock JSON Schema plus published kit keywords x-opensip-order and digest annotations.

Stock jsonschema does not enforce x-opensip-* keywords. This module walks the
owning schema (including $ref) and independently executes those laws.
"""
from __future__ import annotations

import json
from typing import Any
from urllib.parse import urldefrag

from jsonschema import Draft202012Validator
from jsonschema.exceptions import ValidationError
from referencing import Registry, Resource
from referencing.jsonschema import DRAFT202012

from helpers.canonical import C, AdmissionError
from helpers.paths import KIT


class KeywordError(AdmissionError):
    pass


def load_json(rel: str) -> Any:
    return json.loads((KIT / rel).read_text())


def build_registry(documents: dict[str, Any]) -> Registry:
    """documents: {uri: schema_dict}"""
    registry = Registry()
    for uri, schema in documents.items():
        registry = registry.with_resource(uri, Resource.from_contents(schema, default_specification=DRAFT202012))
    return registry


def stock_validate(instance: Any, schema: dict[str, Any], registry: Registry | None = None) -> list[str]:
    if registry is None:
        validator = Draft202012Validator(schema)
    else:
        validator = Draft202012Validator(schema, registry=registry)
    errors = []
    for e in validator.iter_errors(instance):
        errors.append(f"{list(e.absolute_path)}: {e.message}")
    return errors


def check_x_opensip_order(instance: Any, schema: dict[str, Any], *, registry_docs: dict[str, Any] | None = None) -> list[str]:
    """Walk instance/schema and enforce x-opensip-order on arrays."""
    docs = registry_docs or {}
    cache: dict[str, Any] = {}
    faults: list[str] = []

    def resolve(sch: dict[str, Any], base: str) -> tuple[dict[str, Any], str]:
        if "$ref" not in sch:
            return sch, base
        ref = sch["$ref"]
        if ref.startswith("#"):
            uri = base
            frag = ref[1:]
        else:
            uri, frag = urldefrag(ref)
            if not uri:
                uri = base
            if frag and not frag.startswith("/"):
                frag = "/" + frag if frag.startswith("$") else frag
        doc = docs.get(uri)
        if doc is None and uri in docs:
            doc = docs[uri]
        if doc is None:
            # try base document
            doc = docs.get(base)
        if doc is None:
            return sch, base
        target = _pointer(doc, frag) if frag else doc
        if not isinstance(target, dict):
            return sch, uri
        return target, uri

    def walk(inst: Any, sch: dict[str, Any], base: str, path: str) -> None:
        sch, base = resolve(sch, base)
        if "allOf" in sch:
            for sub in sch["allOf"]:
                if isinstance(sub, dict):
                    walk(inst, sub, base, path)
        order = sch.get("x-opensip-order")
        if order is not None and isinstance(inst, list):
            try:
                _check_order(inst, order, path)
            except KeywordError as e:
                faults.append(f"{path}: {e.code}: {e.message}")
        if sch.get("type") == "object" or "properties" in sch:
            if isinstance(inst, dict):
                props = sch.get("properties") or {}
                for k, sub in props.items():
                    if k in inst and isinstance(sub, dict):
                        walk(inst[k], sub, base, f"{path}.{k}")
                addl = sch.get("additionalProperties")
                if isinstance(addl, dict):
                    for k, v in inst.items():
                        if k not in props:
                            walk(v, addl, base, f"{path}.{k}")
        items = sch.get("items")
        if isinstance(items, dict) and isinstance(inst, list):
            for i, v in enumerate(inst):
                walk(v, items, base, f"{path}[{i}]")
        one = sch.get("oneOf") or sch.get("anyOf")
        if isinstance(one, list) and inst is not None:
            # walk matching branch only when unique
            matching = []
            for sub in one:
                if isinstance(sub, dict):
                    matching.append(sub)
            for sub in matching:
                try:
                    walk(inst, sub, base, path)
                except Exception:
                    pass

    root_id = schema.get("$id", "")
    walk(instance, schema, root_id, "$")
    return faults


def _pointer(doc: Any, frag: str) -> Any:
    if not frag:
        return doc
    if frag.startswith("/"):
        parts = frag[1:].split("/")
    else:
        parts = frag.split("/")
    cur = doc
    for p in parts:
        p = p.replace("~1", "/").replace("~0", "~")
        if p == "":
            continue
        if isinstance(cur, dict):
            cur = cur[p]
        else:
            raise KeyError(p)
    return cur


def _item_c_bytes(item: Any) -> bytes:
    return C(item)


def _check_order(arr: list[Any], order: Any, path: str) -> None:
    n = len(arr)
    if order == "sequence":
        return
    if order == "canonical-set":
        keys = [_item_c_bytes(x) for x in arr]
        for i in range(1, n):
            if keys[i] <= keys[i - 1]:
                raise KeywordError("ORDER_CANONICAL_SET", f"{path} not strict ascending unique C bytes")
        if len(set(keys)) != n:
            raise KeywordError("ORDER_UNIQUE", f"{path} duplicate canonical items")
        return
    if order == "canonical-order":
        keys = [_item_c_bytes(x) for x in arr]
        for i in range(1, n):
            if keys[i] < keys[i - 1]:
                raise KeywordError("ORDER_CANONICAL_ORDER", f"{path} not nondecreasing C bytes")
        return
    if order == "utf8":
        if any(type(x) is not str for x in arr):
            raise KeywordError("ORDER_UTF8", f"{path} utf8 order requires string items")
        keys = [x.encode("utf-8") for x in arr]
        for i in range(1, n):
            if keys[i] <= keys[i - 1]:
                raise KeywordError("ORDER_UTF8", f"{path} not strict ascending unique UTF-8")
        return
    if order == "path":
        paths = []
        for x in arr:
            if type(x) is str:
                paths.append(x)
            elif type(x) is dict and "path" in x:
                paths.append(x["path"])
            else:
                raise KeywordError("ORDER_PATH", f"{path} path order requires path field")
        keys = [p.encode("utf-8") for p in paths]
        for i in range(1, n):
            if keys[i] <= keys[i - 1]:
                raise KeywordError("ORDER_PATH", f"{path} paths not unique strict ascending UTF-8")
        return
    if order == "numeric":
        if any(type(x) is not int for x in arr):
            raise KeywordError("ORDER_NUMERIC", f"{path} numeric order requires integers")
        for i in range(1, n):
            if arr[i] <= arr[i - 1]:
                raise KeywordError("ORDER_NUMERIC", f"{path} not strict ascending unique integers")
        return
    if order == "ordinal":
        ords = []
        for x in arr:
            if type(x) is not dict or "ordinal" not in x:
                raise KeywordError("ORDER_ORDINAL", f"{path} ordinal order requires ordinal field")
            ords.append(x["ordinal"])
        if ords != list(range(n)):
            raise KeywordError("ORDER_ORDINAL", f"{path} ordinals not contiguous 0..n-1")
        return
    if order == "predicate":
        keys = []
        for x in arr:
            if type(x) is not dict:
                raise KeywordError("ORDER_PREDICATE", f"{path} predicate order requires objects")
            tup = f"{x.get('ruleId','')},{x.get('subjectId','')},{x.get('predicateId','')}"
            keys.append(tup.encode("utf-8"))
        for i in range(1, n):
            if keys[i] <= keys[i - 1]:
                raise KeywordError("ORDER_PREDICATE", f"{path} not strict ascending unique predicate tuples")
        return
    if order in ("ruleId", "waiverId"):
        keys = []
        for x in arr:
            if type(x) is str:
                keys.append(x.encode("utf-8"))
            elif type(x) is dict and order in x:
                keys.append(str(x[order]).encode("utf-8"))
            else:
                raise KeywordError("ORDER_KEY", f"{path} missing {order}")
        for i in range(1, n):
            if keys[i] <= keys[i - 1]:
                raise KeywordError("ORDER_KEY", f"{path} not strict ascending unique {order}")
        return
    if isinstance(order, dict) and "by" in order:
        fields = order["by"]
        keys = []
        for x in arr:
            if type(x) is not dict:
                raise KeywordError("ORDER_BY", f"{path} by-order requires objects")
            tup = tuple(str(x.get(f, "")).encode("utf-8") for f in fields)
            keys.append(tup)
        for i in range(1, n):
            if keys[i] <= keys[i - 1]:
                raise KeywordError("ORDER_BY", f"{path} not strict ascending unique by {fields}")
        return
    raise KeywordError("ORDER_VOCABULARY", f"{path} x-opensip-order {order!r} outside closed vocabulary")


def collect_digest_annotations(schema: dict[str, Any], instance: Any) -> list[dict[str, Any]]:
    """Collect x-opensip-digest annotations actually present on the instance."""
    found: list[dict[str, Any]] = []

    def walk(inst: Any, sch: dict[str, Any], path: str) -> None:
        if not isinstance(sch, dict):
            return
        if "$ref" in sch and len(sch) == 1:
            return
        ann = sch.get("x-opensip-digest")
        if ann is not None and inst is not None:
            found.append({"path": path, "annotation": ann, "value": inst})
        if isinstance(inst, dict):
            props = sch.get("properties") or {}
            for k, sub in props.items():
                if k in inst:
                    walk(inst[k], sub, f"{path}.{k}")
        if isinstance(inst, list) and isinstance(sch.get("items"), dict):
            for i, v in enumerate(inst):
                walk(v, sch["items"], f"{path}[{i}]")

    walk(instance, schema, "$")
    return found
"}

{"file_path": "/tmp/opensip-design-corrections/consumer-b.v11/output/helpers/status.py", "content": "from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from helpers.paths import OUTPUT, REQUIREMENTS, CONSUMER_ID

REQUIRED_FIELDS = [
    "id",
    "kind",
    "acceptBlocking",
    "status",
    "artifact",
    "firstRefusal",
    "notes",
]


def load_requirements() -> dict[str, Any]:
    return json.loads(REQUIREMENTS.read_text())


def all_ids(req: dict[str, Any]) -> list[dict[str, Any]]:
    rows = []
    for s in req["standing"]:
        rows.append(s)
    for r in req["requirements"]:
        rows.append(r)
    for f in req["futureQualification"]:
        rows.append(f)
    return rows


def init_status() -> dict[str, Any]:
    req = load_requirements()
    items = []
    for row in all_ids(req):
        status = "futureQualification" if row.get("kind") == "futureQualification" else "unexecuted"
        items.append(
            {
                "id": row["id"],
                "kind": row["kind"],
                "acceptBlocking": bool(row.get("acceptBlocking", False)),
                "status": status,
                "artifact": None,
                "firstRefusal": None,
                "notes": "",
                "phase": row.get("phase"),
            }
        )
    return {"consumerId": CONSUMER_ID, "items": items}


def load_status() -> dict[str, Any]:
    p = OUTPUT / "requirement-status.json"
    if p.exists():
        return json.loads(p.read_text())
    return init_status()


def save_status(st: dict[str, Any]) -> None:
    (OUTPUT / "requirement-status.json").write_text(json.dumps(st, indent=2, sort_keys=False) + "\n")


def mark(st: dict[str, Any], rid: str, status: str, *, artifact: str | None = None, notes: str = "", firstRefusal: Any = None) -> None:
    for item in st["items"]:
        if item["id"] == rid:
            item["status"] = status
            if artifact is not None:
                item["artifact"] = artifact
            if notes:
                item["notes"] = notes
            if firstRefusal is not None:
                item["firstRefusal"] = firstRefusal
            return
    raise KeyError(rid)


def write_checkpoint(
    phase: int,
    *,
    executed: list[str],
    required: list[str],
    artifacts: list[str],
    notes: str,
    helper_corrections: list[dict[str, Any]] | None = None,
    failed: list[str] | None = None,
) -> None:
    st = load_status()
    by_id = {i["id"]: i for i in st["items"]}
    unexec = [i for i in required if by_id[i]["status"] == "unexecuted"]
    fail = failed if failed is not None else [i for i in required if by_id[i]["status"] == "failed"]
    rec = {
        "phase": phase,
        "consumerId": CONSUMER_ID,
        "requirementIdsRequired": required,
        "requirementIdsExecuted": executed,
        "requirementIdsUnexecuted": unexec,
        "requirementIdsFailed": fail,
        "artifacts": artifacts,
        "helperCorrections": helper_corrections or [],
        "notes": notes,
    }
    cp = OUTPUT / "checkpoints"
    cp.mkdir(parents=True, exist_ok=True)
    (cp / f"phase-{phase}.json").write_text(json.dumps(rec, indent=2) + "\n")
    save_status(st)


def dump_json(path: Path, obj: Any) -> str:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, indent=2, default=_default) + "\n")
    return str(path)


def _default(o: Any) -> Any:
    if isinstance(o, bytes):
        return o.hex()
    if isinstance(o, set):
        return sorted(o)
    raise TypeError(type(o))
"}

