    try:
        reg = reg.with_resource(sch['$id'], Resource.from_contents(sch, default_specification=DRAFT202012))
    except Exception as e:
        print('reg', sch.get('$id'), e)

def vschema(schema, inst, label):
    try:
        val = Draft202012Validator(schema, registry=reg)
        errs=list(val.iter_errors(inst))
        print(label, len(errs))
        for e in errs[:8]:
            print(' ', list(e.absolute_path), e.message)
    except Exception as e:
        print(label, 'EX', e)

# envelopes
for p in [
    'envelopes/pinned-purge.json',
    'envelopes/config-input.json',
    'envelopes/public-from-internal.json',
    'envelopes/public-termination.json',
    'vectors/repair-descriptor.json',
    'queries/graph-query.json',
]:
    doc=json.loads(Path(p).read_text())
    if 'envelope' in doc:
